chat_template:
{%- if messages[0].role == 'system' %}
    {{- '<|zygpt_turn_start|>system\n' + messages[0].content + '<|zygpt_turn_end|>\n' }}
{%- endif %}
{%- for message in messages %}
    {%- if message.role == 'user' %}
        {{- '<|zygpt_turn_start|>user\n' + message.content + '<|zygpt_turn_end|>\n' }}
    {%- elif message.role == 'assistant' %}
        {{- '<|zygpt_turn_start|>assistant\n' + message.content + '<|zygpt_turn_end|>\n' }}
    {%- endif %}
{%- endfor %}
{%- if add_generation_prompt %}
    {{- '<|zygpt_turn_start|>assistant\n' }}
    {%- if enable_thinking is defined and enable_thinking is false %}
        {{- '<think>\n\n</think>\n\n' }}
    {%- endif %}
{%- endif %}
